/*
 * Header included by code generated by `tools/x86/x86tool lift`. Lifted functions operate on the
 * shared CPU state X with the shared semantics, so the interpreter is an exact differential
 * oracle for them.
 *
 * SPDX-License-Identifier: MIT
 */
#ifndef X86_LIFT_H
#define X86_LIFT_H
#include "x86_sem.h"

/* Port override (a measured exception): replaces the lifted function at an original address.
 *   X86_OVERRIDE(01002345) { ...guest-visible behaviour on X... }
 * The body must leave X.eip = return address (pop it) like the original `ret` would. */
#define X86_OVERRIDE(addr8) void F_##addr8(void)
#endif
